namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeData
{
    public static List<string> Categories =>
    [
        "Breakfast",
        "Lunch",
        "Dinner",
        "Desserts",
        "Snacks",
        "Beverages"
    ];

    private static readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Fluffy Pancakes", Category = "Breakfast",
            Description = "Light and fluffy pancakes perfect for weekend mornings.",
            Ingredients = ["2 cups flour", "2 eggs", "1.5 cups milk", "2 tbsp sugar", "1 tsp baking powder", "Pinch of salt"],
            Steps = ["Mix dry ingredients.", "Whisk eggs and milk together.", "Combine wet and dry ingredients.", "Cook on greased griddle until bubbles form, then flip."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Classic Caesar Salad", Category = "Lunch",
            Description = "A crisp and creamy Caesar salad with homemade dressing.",
            Ingredients = ["1 head romaine lettuce", "1/2 cup croutons", "1/4 cup parmesan", "Caesar dressing", "Lemon juice"],
            Steps = ["Wash and chop lettuce.", "Prepare dressing with garlic, anchovy, lemon, and olive oil.", "Toss lettuce with dressing.", "Top with croutons and parmesan."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A hearty Italian meat sauce served over spaghetti.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 can crushed tomatoes", "1 onion", "3 cloves garlic", "Fresh basil"],
            Steps = ["Cook spaghetti according to package.", "Sauté onion and garlic.", "Brown the beef.", "Add tomatoes and simmer 20 minutes.", "Serve sauce over pasta with fresh basil."],
            AverageRating = 4.8, RatingCount = 25
        },
        new()
        {
            Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cakes with a molten center.",
            Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "1/4 cup sugar", "2 tbsp flour"],
            Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs.", "Add flour gently.", "Bake at 220°C for 12 minutes."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 5, Title = "Guacamole", Category = "Snacks",
            Description = "Fresh and zesty guacamole, perfect with tortilla chips.",
            Ingredients = ["3 ripe avocados", "1 lime", "1/2 onion", "Cilantro", "1 jalapeño", "Salt"],
            Steps = ["Mash avocados in a bowl.", "Dice onion, jalapeño, and cilantro.", "Mix everything together.", "Add lime juice and salt to taste."],
            AverageRating = 4.6, RatingCount = 18
        },
        new()
        {
            Id = 6, Title = "Iced Matcha Latte", Category = "Beverages",
            Description = "A refreshing green tea latte served over ice.",
            Ingredients = ["2 tsp matcha powder", "2 tbsp hot water", "1 cup milk", "Ice", "Sweetener (optional)"],
            Steps = ["Sift matcha into a bowl.", "Add hot water and whisk until smooth.", "Fill a glass with ice.", "Pour milk over ice, then add matcha."],
            AverageRating = 4.3, RatingCount = 10
        }
    ];

    public static List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public static Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public static List<Recipe> GetAll() => _recipes;
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _currentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              style="@(star <= (_hoverRating > 0 ? _hoverRating : _currentRating) ? "color: gold;" : "color: #ccc;")">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double InitialRating { get; set; }

    private int _currentRating;
    private int _hoverRating;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        if (!_submitted)
        {
            _currentRating = (int)Math.Round(InitialRating);
        }
    }

    private void SetRating(int rating)
    {
        _currentRating = rating;
        _submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin: 1rem 0;
}

.star {
    font-size: 1.75rem;
    cursor: pointer;
    transition: color 0.15s;
}

.rating-label {
    margin-right: 0.5rem;
    font-weight: 500;
}

