@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>@Category Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@Category</li>
        </ol>
    </nav>

    <h1>@Category Recipes</h1>

    @if (_recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet. Be the first to <a href="submit">submit one</a>!</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in _recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">
                                <a href="recipes/detail/@recipe.Id">@recipe.Title</a>
                            </h4>
                            <p class="card-text">@recipe.Description</p>
                            <div class="text-muted">
                                <span style="color: gold;">★</span> @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private List<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeData.GetByCategory(Category);
    }
}

@page "/recipes/detail/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (_recipe is not null)
            {
                <li class="breadcrumb-item"><a href="recipes/@_recipe.Category.ToLower()">@_recipe.Category</a></li>
                <li class="breadcrumb-item active">@_recipe.Title</li>
            }
        </ol>
    </nav>

    @if (_recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@_recipe.Title</h1>
        <p class="lead">@_recipe.Description</p>

        <div class="mb-3 text-muted">
            <span style="color: gold;">★</span> @_recipe.AverageRating.ToString("F1") average (@_recipe.RatingCount ratings)
        </div>

        <StarRating RecipeId="@_recipe.Id" InitialRating="@_recipe.AverageRating" />

        <div class="row mt-4">
            <div class="col-md-5">
                <h3>Ingredients</h3>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in _recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
            <div class="col-md-7">
                <h3>Steps</h3>
                <ol class="list-group list-group-numbered list-group-flush">
                    @foreach (var step in _recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeData.GetById(Id);
    }
}

